<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RefreshRight, Compass, Clock, Flag } from '@element-plus/icons-vue'
import AppShell from '../components/product/AppShell.vue'
import PathProgressRing from '../components/path/PathProgressRing.vue'
import PathTimeline from '../components/path/PathTimeline.vue'
import { usePathStore } from '../stores/path'
import type { PathStepStatus } from '../types/path'

const store=usePathStore(); const goal=ref(''); const course=ref('Python'); const showPlanner=ref(false); const confirmReplan=ref(false); const notice=ref('')
const nextStep=computed(()=>store.path?.path_data.find(s=>s.status!=='completed'))
async function generate(){if(!goal.value.trim()||!course.value.trim()) return; try{await store.generate({message:goal.value.trim(),course:course.value.trim()});showPlanner.value=false;confirmReplan.value=false;notice.value='新的学习航线已生成'}catch{}}
async function update(step:number,status:PathStepStatus){try{await store.updateStep(step,status);notice.value=status==='completed'?`第 ${step} 站已点亮`:'已进入这一站'}catch{}}
function startReplan(){goal.value='';showPlanner.value=true;confirmReplan.value=false}
onMounted(store.load)
</script>
<template><AppShell><div class="path-page"><header class="hero"><div><span class="kicker"><Compass/>个性化学习航线</span><h1>把远方，拆成今天能走的一步</h1><p>小智析析会依据你的目标规划 5–8 个学习站点，并记住每一次进展。</p></div><PathProgressRing v-if="store.path" :value="store.progress" /></header>
<div v-if="notice" class="notice" role="status">{{ notice }}<button aria-label="关闭" @click="notice=''">×</button></div>
<div v-if="store.error" class="error" role="alert"><span>{{ store.error }}</span><button @click="store.load">重试</button></div>
<div v-if="store.loading" class="loading" aria-label="正在读取学习路径"><i v-for="n in 4" :key="n"/></div>
<template v-else-if="store.path"><section class="summary"><div><Flag/><span><small>下一站</small><strong>{{ nextStep?.topic || '航线已全部点亮' }}</strong></span></div><div><Clock/><span><small>剩余预计</small><strong>{{ store.remainingMinutes }} 分钟</strong></span></div><div class="count"><small>已点亮</small><strong>{{ store.completedCount }} / {{ store.path.path_data.length }}</strong></div><button class="replan" @click="confirmReplan=true"><RefreshRight/>重新规划</button></section><PathTimeline :path="store.path" :updating-step="store.updatingStep" @update="update" /></template>
<section v-else class="empty"><div class="map-mark"><Compass/></div><span>学习星图·待规划</span><h2>你的第一条航线，从一个具体目标开始</h2><p>这里还没有学习路径。告诉我你想掌握什么，系统才会根据真实画像开始规划。</p><button class="primary" @click="showPlanner=true">规划第一条路径</button></section>
<div v-if="showPlanner" class="overlay" @click.self="showPlanner=false"><form class="modal" @submit.prevent="generate"><button class="close" type="button" aria-label="关闭" @click="showPlanner=false">×</button><span class="kicker">航线规划</span><h2>{{ store.path?'重新设定学习目标':'你想到达哪里？' }}</h2><label>课程或领域<input v-model="course" maxlength="200" placeholder="例如：Python 程序设计"/></label><label>具体目标<textarea v-model="goal" maxlength="2000" rows="4" placeholder="例如：从零掌握 Python，并独立完成一个数据分析项目"/></label><button class="primary" :disabled="store.generating||!goal.trim()||!course.trim()">{{ store.generating?'正在绘制航线…':'生成学习路径' }}</button></form></div>
<div v-if="confirmReplan" class="overlay" @click.self="confirmReplan=false"><div class="modal confirm"><h2>确认重新规划？</h2><p>新路径生成后，当前航线将不再活跃。已有进度不会被冒充迁移到新路径。</p><div><button @click="confirmReplan=false">取消</button><button class="danger" @click="startReplan">继续重新规划</button></div></div></div></div></AppShell></template>
<style scoped>.path-page{--ink:#27241f;--muted:#716b63;--accent:#df6847;max-width:1120px;margin:auto;padding:22px 20px 70px}.hero{display:flex;align-items:center;justify-content:space-between;gap:36px;padding:38px 0 34px;border-bottom:1px solid #ddd9d1}.hero>div:first-child{max-width:720px}.kicker{display:inline-flex;align-items:center;gap:7px;color:#a64d36;font-size:12px;font-weight:750;letter-spacing:.08em}.kicker svg{width:17px}.hero h1{font-family:Georgia,'Noto Serif SC',serif;font-size:clamp(30px,4vw,50px);line-height:1.16;letter-spacing:0;margin:12px 0;color:var(--ink)}.hero p,.empty p,.confirm p{color:var(--muted);line-height:1.75}.summary{margin-top:24px;display:grid;grid-template-columns:2fr 1.2fr 1fr auto;align-items:center;border:1px solid #ddd9d1;border-radius:8px;background:#fff}.summary>div{display:flex;gap:12px;align-items:center;padding:17px 20px;border-right:1px solid #e6e2dc}.summary svg{width:20px;color:var(--accent)}.summary span,.summary small,.summary strong{display:block}.summary small{color:#817b72;font-size:11px;margin-bottom:3px}.summary strong{font-size:14px;color:var(--ink)}.replan{margin:0 14px;display:flex;align-items:center;gap:6px;border:0;background:transparent;color:#6a645c;cursor:pointer}.replan svg{width:16px}.empty{text-align:center;max-width:620px;margin:80px auto}.map-mark{width:82px;height:82px;margin:auto;display:grid;place-items:center;border:1px solid #d7d1c8;border-radius:50%;background:#fff}.map-mark svg{width:34px;color:var(--accent)}.empty>span{display:block;margin:20px 0 8px;color:#a14e38;font-size:12px}.empty h2,.modal h2{font-family:Georgia,'Noto Serif SC',serif;letter-spacing:0;font-size:28px;color:var(--ink)}button{font:inherit}.primary{border:0;border-radius:6px;padding:12px 20px;background:var(--accent);color:#fff;font-weight:700;cursor:pointer}.primary:disabled{opacity:.55;cursor:wait}.error,.notice{margin-top:16px;padding:12px 15px;border-radius:6px;display:flex;justify-content:space-between}.error{background:#fff0eb;color:#9b3e28}.notice{background:#eaf5f0;color:#256e5d}.error button,.notice button{border:0;background:transparent;color:inherit}.loading{max-width:850px;margin:40px auto}.loading i{display:block;height:140px;background:#eeece7;border-radius:8px;margin:14px;animation:pulse 1.2s infinite alternate}@keyframes pulse{to{opacity:.45}}.overlay{position:fixed;z-index:40;inset:0;background:rgba(28,26,23,.48);display:grid;place-items:center;padding:18px}.modal{position:relative;width:min(520px,100%);background:#fff;border-radius:8px;padding:30px;box-shadow:0 24px 70px rgba(0,0,0,.18)}.close{position:absolute;right:15px;top:12px;border:0;background:transparent;font-size:25px}.modal label{display:block;margin:18px 0;color:#534f49;font-size:13px;font-weight:650}.modal input,.modal textarea{box-sizing:border-box;width:100%;margin-top:7px;padding:11px 12px;border:1px solid #ccc6bd;border-radius:5px;font:inherit;resize:vertical}.modal .primary{width:100%}.confirm div{display:flex;justify-content:flex-end;gap:10px}.confirm button{padding:9px 13px;border:1px solid #ccc6bd;border-radius:5px;background:#fff}.confirm .danger{background:#b54e36;color:#fff;border-color:#b54e36}@media(max-width:760px){.hero{align-items:flex-start}.hero :deep(.ring){width:92px;flex:0 0 92px}.summary{grid-template-columns:1fr 1fr}.summary>div:nth-child(2){border-right:0}.replan{padding:14px}.hero h1{font-size:32px}}@media(max-width:520px){.hero{display:block}.hero :deep(.ring){margin:24px auto 0}.summary{grid-template-columns:1fr}.summary>div{border-right:0;border-bottom:1px solid #e6e2dc}.summary .count{display:none}}</style>
